-- VISITAS fictícias da RBN 94,3 (complemento de 20261029110000_DEMO_rbn_dados_ficticios.sql).
-- Rode DEPOIS da carga principal: usa os anunciantes DEMO-SEED dela. Saem junto no script de limpeza
-- (20261029110100), que apaga as visitas ligadas aos anunciantes demo.

DO $demo$
DECLARE
  v_emp uuid;
  v_count int;
  v_users uuid[];
  v_unid text[];
  v_cli bigint;
  v_lead bigint;
BEGIN
  SELECT count(*) INTO v_count FROM empresas WHERE nome ILIKE '%rbn%';
  IF v_count <> 1 THEN RAISE EXCEPTION 'Esperava 1 empresa com "RBN" no nome, achou %. Ajuste o filtro.', v_count; END IF;
  SELECT id INTO v_emp FROM empresas WHERE nome ILIKE '%rbn%';
  IF NOT EXISTS (SELECT 1 FROM clientes WHERE empresa_id = v_emp AND observacao_risco = 'DEMO-SEED') THEN RAISE EXCEPTION 'Rode antes a carga principal (20261029110000_DEMO_rbn_dados_ficticios.sql).'; END IF;
  IF EXISTS (SELECT 1 FROM visitas v JOIN clientes c ON c.id = v.cliente_id WHERE v.empresa_id = v_emp AND c.observacao_risco = 'DEMO-SEED') THEN RAISE EXCEPTION 'Visitas demo já carregadas.'; END IF;
  v_users := ARRAY(SELECT id FROM profiles WHERE empresa_id = v_emp ORDER BY (cargo = 'diretor') DESC, id);
  v_unid := ARRAY(SELECT nome FROM unidades WHERE empresa_id = v_emp ORDER BY nome);
  IF array_length(v_unid, 1) IS NULL THEN v_unid := ARRAY['RBN 94,3']; END IF;

  SELECT id INTO v_cli FROM clientes WHERE empresa_id = v_emp AND nome_empresa = 'Supermercado Bom Preço' AND observacao_risco = 'DEMO-SEED' LIMIT 1;
  SELECT id INTO v_lead FROM leads WHERE empresa_id = v_emp AND origem = 'demo_seed' AND client_id = v_cli AND created_at::date <= '2026-10-16' ORDER BY created_at DESC LIMIT 1;
